/* eslint-disable */
import { ACTIONS_AJAX_ROOM } from "./lib/actions";
import { TEMPLATES } from "./lib/template";
import { ButtonStateManager } from "./lib/button_state";
import { handleError, handleNetworkError, handleParseError } from "./lib/error_handler";
import { ApiService } from "./lib/api_service";
import { TemplateRenderer } from "./lib/template_renderer";

M.mod_tutoom = M.mod_tutoom || {};

// Create shared service instances
const apiService = new ApiService();
const templateRenderer = new TemplateRenderer();

export const getRoom = async () => {
  const tutoom = window.tutoom;
  if (!tutoom || tutoom === undefined) throw new Error("Tutoom data is empty");

  const { baseUrl, id: ID } = tutoom;

  const url = `${baseUrl}?action=${ACTIONS_AJAX_ROOM.GET_ROOM}&sesskey=${M.cfg.sesskey}&id=${ID}`;
  return await window.fetch(url);
};

export const startRoom = async (e) => {
  e.preventDefault();

  const { isModerator } = apiService.getTutoomData();
  const elementButton = document.getElementById("tutoom-start-button");
  const buttonState = new ButtonStateManager(elementButton);
  buttonState.showSpinner();

  try {
    const result = await apiService.fetchAndParse(
      ACTIONS_AJAX_ROOM.START_ROOM,
      { logoutUrl: window.location.href }
    );

    if (!result.success) {
      await templateRenderer.renderError(handleParseError(), TEMPLATES.MAIN_SECTION);
      return;
    }

    const { error, roomId, numParticipants, roomDate } = result.data;

    if (error) {
      await templateRenderer.renderError(handleError(error), TEMPLATES.MAIN_SECTION);
      return;
    }

    if (roomId) {
      await templateRenderer.render({
        data: {
          roomid: roomId,
          ismoderator: isModerator,
          roomdate: roomDate,
          participantscount: `${numParticipants}`,
          istextpluralparticipant: numParticipants > 1,
        },
        type: TEMPLATES.MAIN_SECTION
      });
    }
  } catch (error) {
    console.error(error);
    await templateRenderer.renderError(handleNetworkError(error), TEMPLATES.MAIN_SECTION);
  } finally {
    buttonState.restore();
  }
};

export const joinRoom = async (e) => {
  e.preventDefault();

  const elementButton = document.getElementById("tutoom-join-button");
  const buttonState = new ButtonStateManager(elementButton);
  buttonState.showSpinner();

  try {
    const result = await apiService.fetchAndParse(ACTIONS_AJAX_ROOM.JOIN_ROOM);

    if (!result.success) {
      await templateRenderer.renderError(handleParseError(), TEMPLATES.MAIN_SECTION);
      return;
    }

    const { error, joinurl } = result.data;

    if (error) {
      if (error.statuscode === 404) {
        await templateRenderer.render({
          data: { error: true, roomidnotexists: true },
          type: TEMPLATES.MAIN_SECTION
        });
      } else {
        await templateRenderer.renderError(handleError(error), TEMPLATES.MAIN_SECTION);
      }
      return;
    }

    if (joinurl) {
      window.location.href = joinurl;
    }

  } catch (error) {
    console.error(error);
    await templateRenderer.renderError(handleNetworkError(error), TEMPLATES.MAIN_SECTION);
  } finally {
    buttonState.restore();
  }
};

export const endRoom = async (e) => {
  e.preventDefault();

  const elementButton = document.getElementById("tutoom-end-button");
  const value = e.target.value;

  const buttonState = new ButtonStateManager(elementButton, 'DANGER');
  buttonState.showSpinner();

  try {
    const result = await apiService.fetchAndParse(
      ACTIONS_AJAX_ROOM.END_ROOM,
      { roomId: value }
    );

    if (!result.success) {
      await templateRenderer.renderError(handleParseError(), TEMPLATES.MAIN_SECTION);
      return;
    }

    const { error, deleted } = result.data;

    if (error) {
      if (error.statuscode === 404) {
        await templateRenderer.render({
          data: { error: true, roomidnotexists: true },
          type: TEMPLATES.MAIN_SECTION
        });
      } else {
        await templateRenderer.renderError(handleError(error), TEMPLATES.MAIN_SECTION);
      }
      return;
    }

    if (deleted) {
      await clearMainSection(e);
    }
  } catch (error) {
    console.error(error);
    await templateRenderer.renderError(handleNetworkError(error), TEMPLATES.MAIN_SECTION);
  } finally {
    buttonState.restore();
  }
};

export const clearMainSection = async (e) => {
  e.preventDefault();

  const { isModerator } = apiService.getTutoomData();

  await templateRenderer.render({
    data: { roomid: null, ismoderator: isModerator },
    type: TEMPLATES.MAIN_SECTION
  });
};
