/**
 * Centralized error handler for Tutoom client-side errors.
 *
 * Maps error responses from the API to user-friendly messages and provides
 * recovery suggestions.
 *
 * @module mod_tutoom/lib/error_handler
 * @copyright 2025 onwards, Tutoom Inc.
 * @license http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

/**
 * Handle API error response and format for display.
 *
 * @param {Object} error - Error object from API response
 * @param {string} error.code - Error code
 * @param {string} error.message - Error message
 * @param {number} error.statuscode - HTTP status code
 * @param {string} error.suggestion - Recovery suggestion
 * @param {string} [error.requestid] - Request ID for debugging
 * @returns {Object} Formatted error data for template rendering
 */
export const handleError = (error) => {
  const errorData = {
    error: true,
    errorcode: error.code || `HTTP_${error.statuscode}`,
    errormessage: error.message || 'An unexpected error occurred',
    suggestion: error.suggestion || 'Please try again or contact your administrator.',
    retryable: error.retryable || false,
  };

  if (error.requestid) {
    errorData.requestid = error.requestid;
  }

  return errorData;
};

/**
 * Handle network/fetch errors (no response from server).
 *
 * @param {Error} err - JavaScript Error object
 * @returns {Object} Formatted error data
 */
export const handleNetworkError = (err) => {
  return {
    error: true,
    errorcode: 'NETWORK_ERROR',
    errormessage: 'Network error: Unable to connect to Tutoom service',
    suggestion: 'Please check your internet connection and try again.',
    retryable: true,
  };
};

/**
 * Handle JSON parse errors (invalid response format).
 *
 * @returns {Object} Formatted error data
 */
export const handleParseError = () => {
  return {
    error: true,
    errorcode: 'PARSE_ERROR',
    errormessage: 'Invalid response from server',
    suggestion: 'Please try again. If the problem persists, contact your administrator.',
    retryable: true,
  };
};

/**
 * Check if error is retryable.
 *
 * @param {Object} error - Error object
 * @returns {boolean} True if error can be retried
 */
export const isRetryable = (error) => {
  if (error.retryable !== undefined) {
    return error.retryable;
  }

  // Default retryable errors based on status code
  const retryableStatusCodes = [0, 429, 500, 502, 503, 504];
  return retryableStatusCodes.includes(error.statuscode);
};

/**
 * Get retry delay in milliseconds using exponential backoff.
 *
 * @param {number} attempt - Retry attempt number (0-based)
 * @returns {number} Delay in milliseconds
 */
export const getRetryDelay = (attempt = 0) => {
  // Exponential backoff: 2^attempt seconds, capped at 60 seconds
  const delaySeconds = Math.min(Math.pow(2, attempt), 60);
  return delaySeconds * 1000;
};
