/* eslint-disable */

import { ACTIONS_AJAX_RECORDING } from "./lib/actions";
import { TEMPLATES } from "./lib/template";
import { handleError, handleNetworkError, handleParseError } from "./lib/error_handler";
import { ApiService } from "./lib/api_service";
import { TemplateRenderer } from "./lib/template_renderer";
import { DomManager } from "./lib/dom_manager";

M.mod_tutoom = M.mod_tutoom || {};

// Create shared service instances
const apiService = new ApiService();
const templateRenderer = new TemplateRenderer();
const domManager = new DomManager();

export const joinPlayback = async (e) => {
  e.preventDefault();

  const { roomid } = e.target.dataset;

  try {
    const result = await apiService.fetchAndParse(
      ACTIONS_AJAX_RECORDING.JOIN_PLAYBACK,
      { roomId: roomid }
    );

    if (!result.success) {
      await templateRenderer.renderError(handleParseError(), TEMPLATES.RECORDING_SECTION);
      return;
    }

    const { error, joinurl } = result.data;

    if (error) {
      await templateRenderer.renderError(handleError(error), TEMPLATES.RECORDING_SECTION);
      return;
    }

    if (joinurl) {
      window.location.href = joinurl;
    }

  } catch (error) {
    console.error(error);
    await templateRenderer.renderError(handleNetworkError(error), TEMPLATES.RECORDING_SECTION);
  }
};

export const getRecordings = async ({ page = 1 }) => {
  try {
    // Show loader recordings.
    domManager.clear("tutoom-recordings-table-content");
    domManager.show("tutoom_view_recordings_loading");

    const result = await apiService.fetchAndParse(
      ACTIONS_AJAX_RECORDING.GET_RECORDINGS,
      { page }
    );

    if (!result.success) {
      domManager.hide("tutoom_view_recordings_loading");
      await templateRenderer.renderError(handleParseError(), TEMPLATES.RECORDING_SECTION);
      return;
    }

    const { error, recordings, pageSize, totalRecords } = result.data;

    if (error) {
      domManager.hide("tutoom_view_recordings_loading");
      await templateRenderer.renderError(handleError(error), TEMPLATES.RECORDING_SECTION);
      return;
    }

    let records = []
    let isemptyrecordings = false
    if(recordings === undefined || recordings.length == 0){
      isemptyrecordings = true
    } else{
      
      records = recordings.map((r, index) => {
      const isLastIndex = index === recordings.length - 1;
      const renderRowSeparator = !isLastIndex;

      // Map API fields to expected format
      const recordingDuration = r.duration || 0;
      const roomId = r.id || '';
      const recordingThumbnail = r.thumbnailUrl || '';

      // Calculate duration display
      const hours = Math.floor(recordingDuration / 3600);
      const minutes = Math.floor((recordingDuration % 3600) / 60) + " min";
      const duration = hours > 0 ? `${hours}h ${minutes}` : minutes;

      // Use server-formatted dates (already timezone-aware from PHP userdate)
      const date = r.formattedDate || '';
      const time = r.formattedTime || '';

      return {
        roomid: roomId,
        thumbnail: recordingThumbnail,
        duration,
        date,
        time,
        renderRowSeparator,
      };
    });
    }
    

    const callbackBeforeRender = () => {
      domManager.hide("tutoom_view_recordings_loading");
    };

    const callbackAfterRender = () => {
      const thumbnails = document.querySelectorAll(".thumbnail");
      thumbnails.forEach((thumbnail) => {
        thumbnail.addEventListener("click", joinPlayback);
      });
    };

    await templateRenderer.render({
      data: { recordings: records, isemptyrecordings: isemptyrecordings, countrecordings: totalRecords },
      type: TEMPLATES.RECORDING_SECTION,
      callbackBeforeRender,
      callbackAfterRender,
    });

    // Clear element cache to ensure fresh DOM references for pagination
    templateRenderer.clearCache();


    if(recordings != undefined && recordings.length > 0){
      const totalPages = Math.ceil(totalRecords / pageSize);
      const pages = [...Array(totalPages).keys()].map((n) => ({
        number: n + 1,
        isSelected: n + 1 === page,
      }));
  
      const currentPage = pages.findIndex((p) => p.isSelected) + 1;
  
      if (totalPages > 1) {
        const dataPagination = {
          pages,
          disablePrevious: page === 1,
          disableNext: page === totalPages,
          currentPage,
        };

        await templateRenderer.render({
          data: dataPagination,
          type: TEMPLATES.RECORDING_PAGINATION,
        });
      }
    }


  } catch (error) {
    console.error(error);
    domManager.hide("tutoom_view_recordings_loading");
    await templateRenderer.renderError(handleNetworkError(error), TEMPLATES.RECORDING_SECTION);
  }
};
